CREATE TABLE invoices (id TEXT PRIMARY KEY, business_id TEXT NOT NULL REFERENCES businesses(id), customer_id TEXT NOT NULL REFERENCES customers(id), state TEXT NOT NULL DEFAULT 'draft', currency CHAR(3) NOT NULL DEFAULT 'USD', total_cents BIGINT NOT NULL, due_date TIMESTAMPTZ NOT NULL, idempotency_key TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK (total_cents >= 0), CHECK (state IN ('draft','open','paid','void','uncollectible')));
